  "updates": [
    {
      "question_id": "Q1",
      "answered_aspects": [
        {
          "aspect_id": "Q1-A1",
          "claim": "袁府君即袁山松，隆安五年死於滬瀆，與正文『戰於滬瀆』相合。",
          "evidence": [
            {
              "ref": "J06",
              "quote": "隆安五年，袁山松死於滬瀆。"
            }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [
        {
          "conflict_id": "Q1-C1",
          "description": "陳遺官職的記載不同：正文作『郡主簿』，而宋躬《孝子傳》及《南史》僅稱『少為郡吏』，不知其為主簿。",
          "evidence": [
            {
              "ref": "J02",
              "quote": "宋躬孝子傳及南史均止云「少為郡吏」，不知其為主簿也。"
            }
          ]
        }
      ],
      "reading_sufficient": true,
      "historical_verification_open": true
    },
    {
      "question_id": "Q2",
      "answered_aspects": [
        {
          "aspect_id": "Q2-A1",
          "claim": "孫恩之亂起於五斗米道，孫泰因謀反被誅，孫恩逃於海上，後聚衆十萬人攻沒郡縣，是一場大規模叛亂。",
          "evidence": [
            {
              "ref": "L02",
              "quote": "泰事五斗米道以謀反誅恩逸逃於海上"
            },
            {
              "ref": "L03",
              "quote": "聚衆十萬人攻沒郡縣"
            }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [
        {
          "conflict_id": "Q2-C1",
          "description": "孫恩的結局記載衝突：一說被臨海太守辛昺斬首，一說窮蹙赴海自沈。",
          "evidence": [
            {
              "ref": "L03",
              "quote": "臨海太守辛昺斬首送之"
            },
            {
              "ref": "J04",
              "quote": "恩窮蹙赴海自沈"
            }
          ]
        }
      ],
      "reading_sufficient": true,
      "historical_verification_open": true
    },
    {
      "question_id": "Q3",
      "answered_aspects": [],
      "unanswered_aspects": [
        {
          "aspect_id": "Q3-U1",
          "gap": "注釋未說明陳遺如何在潰敗中保存焦飯，亦未說明焦飯數量是否足以支持他存活，使『獨活』與孝報的因果關聯缺乏具體支撐。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": false
    }
  ]
}

